"""大题批次3（33 题：435~472 指定题号）：「参考答案」-> 「题目解析 + 标准答案」（代码题附完整代码）。
用法：python D:\\dev-tools\\apply_big_batch.py D:\\dev-tools\\batch_big_3_data.py"""
NEW = {
    435: ("考点是位运算拆分十六进制：一个字节含 8 个二进制位，恰可分成高 4 位与低 4 位两个「半字节」，每个半字节取值 0~15，与查表数组中的 16 个字符一一对应——高 4 位用 v>>4 取得（右移后结果自然落在 0~15），低 4 位用 v&0x0F 掩码取得（只保留最低 4 位）。输出约定为大写 A~F，字符串需 2 个字符再加结尾 '\\0' 共 3 字节。整体 O(1) 时间与空间。易错点：忘记补 '\\0'；高低位顺序写反；低 4 位不用掩码（若原样拿 v 作下标会越界访问查表数组）；输出缓冲小于 3 字节。延伸：多字节数据可循环按「字节→两位字符」处理，格式化输出等价于 printf(\"%02X\")。",
          "完整函数（含调用示例）如下：\n```c\n#include <stdint.h>\n\n/* 8 位无符号整数转十六进制字符串（大写；out 至少 3 字节） */\nvoid u8_to_hexstr(uint8_t v, char *out)\n{\n    const char *digits = \"0123456789ABCDEF\";\n    out[0] = digits[v >> 4];      /* 高 4 位 */\n    out[1] = digits[v & 0x0F];    /* 低 4 位 */\n    out[2] = '\\0';                /* 字符串结尾 */\n}\n/* 调用示例：char s[3]; u8_to_hexstr(0xAB, s); 得到 s = \"AB\" */\n```\n要点：移位取高 4 位、掩码取低 4 位，各 16 种取值恰好一一对应表内字符；O(1) 时间与空间。"),
    436: ("两种解法：①循环累加带符号项——从 1 到 100 逐项求和，每加一项后把符号翻转（+1、-2、+3、-4……），共 100 次加法，结果 -50；②成对化简——(1-2)+(3-4)+……+(99-100)，每对恰为 -1、共 50 对，直接得 -1×50=-50，O(1)。考查点是发现规律的能力，面试可两种都说。易错点：符号翻转时机（先加后翻，翻早了首项就成负号）；边界 100 为偶数恰好凑 50 对；输出 -50。",
          "完整程序如下（循环法；成对化简说明附后）：\n```c\n#include <stdio.h>\n\nint main(void)\n{\n    int sum = 0, sign = 1;\n    for (int i = 1; i <= 100; i++) {\n        sum += sign * i;       /* 累加带符号项 */\n        sign = -sign;          /* 下一项符号翻转 */\n    }\n    printf(\"%d\\n\", sum);     /* 输出 -50 */\n    return 0;\n}\n```\n要点：结果 -50；也可成对化简 (1-2)+(3-4)+……+(99-100)=(-1)×50=-50 直接作答。"),
    437: ("考查按时序图写位操作程序：①RST 是低有效复位信号——时序开始时按题图产生复位动作（参考实现为拉低、延时、再拉高释放）；②图注说明 A0、D0 分别是地址与数据的最低位，即地址和数据都「最低位先发」（LSB first），所以循环用 (x>>i)&1 从第 0 位取到第 7 位；③写位时机：SCLK 先拉低、在低电平期间把该位摆到 I/O 上，再拉高 SCLK 产生写入沿，让从机采样该位；④结束把 SCLK 拉回低。共循环 16 次（8 位地址 + 8 位数据）。另：题面签名 Void 是大小写笔误，答案按 void 写。易错点：位序写成 MSB 先发；输出位时漏 &1 掩码；时钟沿方向写反；RST 时序漏写。",
          "完整函数如下（引脚初始化题目已声明省略）：\n```c\nvoid SendByte(u8 Addr, u8 Data)\n{\n    u8 i;\n    RST = 0;                       /* 复位拉低（按时序） */\n    delay();\n    RST = 1;                       /* 释放复位 */\n    for (i = 0; i < 8; i++) {      /* 先发 8 位地址 A0~A7（LSB 先） */\n        SCLK = 0;\n        IO = (Addr >> i) & 1;\n        SCLK = 1;                  /* 上升沿写入 */\n    }\n    for (i = 0; i < 8; i++) {      /* 再发 8 位数据 D0~D7 */\n        SCLK = 0;\n        IO = (Data >> i) & 1;\n        SCLK = 1;\n    }\n    SCLK = 0;                      /* 时钟回低 */\n}\n```\n要点：位循环 + 时钟沿匹配题图；A0/D0 为最低位 ⇒ LSB 先发；地址在前、数据在后。"),
    439: ("思路是计数哈希：字符的 ASCII 码范围只有 0~255，直接开 256 个计数桶，用字符码值当下标 O(1) 定位；一趟遍历每个字符令 cnt[c]++，同时维护当前最大计数 max 与对应字符 res，一旦某计数超过 max 就地更新。总时间 O(n)、空间 O(256) 即 O(1)。边界与细节：用 unsigned char 接收字符再作下标，避免 char 为有符号时负值越界；并列时用严格大于判断，保证返回「最先达到该次数」的字符；空串无解（参考实现返回 0，调用方需自行确认非空）；'\\0' 是串尾标志，不计入统计。易错点：数组未清零；下标未转无符号；更新条件写成 >=（会返回最后出现的字符，语义随约定但需说明）。",
          "完整函数（含调用示例）如下：\n```c\n/* 返回出现次数最多的字符；空串返回 0（调用方确认非空） */\nchar get_max_char_in_strings(char *str)\n{\n    int cnt[256] = {0}, max = 0;\n    char res = 0;\n    for (char *p = str; *p; p++) {\n        unsigned char c = *p;              /* 防止负下标 */\n        if (++cnt[c] > max) {              /* 严格大于：并列取先出现者 */\n            max = cnt[c];\n            res = c;\n        }\n    }\n    return res;\n}\n/* 调用示例：get_max_char_in_strings(\"aabbbcc\") 返回 'b' */\n```\n要点：计数哈希一趟 O(n)、O(1) 空间；转 unsigned char 防负下标；'\\0' 不计入。"),
    440: ("指针版原地删除核心是「读写双指针」：读指针 s 从头扫到尾，写指针 w 始终指向结果串下一个可写位置；遇到要保留的字符（≠c）就 *w++=*s 写回并前移，遇到目标字符就跳过（不写、不移动 w）；扫描结束后在 w 处补 '\\0' 截断。因为 w 只可能落后于 s（删除只会让结果更短），覆盖写不会破坏尚未读取的数据，故不需要额外缓冲区。时间 O(n)、空间 O(1)。测试例程要点：测试串必须用可修改的字符数组（如 char t[]=\"ababb\"），不能用字符串字面量（只读区，写入会崩溃）；两个用例覆盖「有删除」与「无删除」。易错点：忘记补 '\\0'；用字面量测试；写指针前移条件写反。",
          "完整函数与测试例程如下：\n```c\n#include <stdio.h>\n\n/* 原地删除字符串中所有等于 c 的字符（双指针） */\nvoid delete_char(char *s, char c)\n{\n    char *w = s;                    /* 写指针：结果串结尾 */\n    while (*s) {                    /* 读指针：遍历原串 */\n        if (*s != c) *w++ = *s;     /* 保留：写回并前移 */\n        s++;                        /* 命中 c：跳过 */\n    }\n    *w = '\\0';                      /* 截断新结尾 */\n}\n\nint main(void)\n{\n    char t1[] = \"ababb\";\n    delete_char(t1, 'a');\n    puts(t1);                       /* bbb */\n\n    char t2[] = \"ababb\";\n    delete_char(t2, 'c');\n    puts(t2);                       /* ababb（没有可删字符） */\n    return 0;\n}\n```\n要点：读写双指针原地 O(n)/O(1)；测试必须用可修改的字符数组；结果长度不增，覆盖安全。"),
    441: ("求「最长连续相同字符游程」用游程扫描：固定起点 i，用 j 向后一直推进到与 s[i] 不同处，j-i 即这一段长度；与历史最优 best_len 比较（严格大于才更新，保证并列时返回最先出现的一段），记录起点与终点；然后令 i=j 直接跳到下一段，避免重复扫描——整体只扫一遍 O(n)。全程不用任何库函数。下标约定：题面样例「12ffffcced」给出 startpos=3、endpos=6，即第 3~6 个字符、按 1 基计数——实现里 0 基下标 i 对应第 i+1 个字符，故返回 i+1 与 j（j-1 为 0 基末下标）。边界：空串约定返回 -1、-1（无解）；整串同字符返回第 1 个到第 len 个；单字符返回 1、1。易错点：1 基/0 基约定不注明（结果差 1）；推进写成 i++（退化成 O(n²) 或死循环）；并列取舍未说明。延伸：该思想是「游程编码」的基础。",
          "完整函数（含调用示例）如下：\n```c\n/* 找最长同字符游程：*sp 与 *ep 返回起始/结束位置（1 基计数，与题面样例一致）；空串返回 -1、-1。\n   不用任何库函数 */\nvoid longest_same(const char *s, int *sp, int *ep)\n{\n    int best_len = 0, i = 0;\n    *sp = -1;\n    *ep = -1;\n    while (s[i]) {\n        int j = i;\n        while (s[j] == s[i]) j++;       /* 向后找本段末尾 */\n        if (j - i > best_len) {         /* 严格大于：并列保留先出现段 */\n            best_len = j - i;\n            *sp = i + 1;                    /* 1 基起始：第 i+1 个字符 */\n            *ep = j;                /* 1 基结束（0 基末下标 j-1 再 +1） */\n        }\n        i = j;                          /* 直接跳到下一段 */\n    }\n}\n/* 调用示例：int sp, ep; longest_same(\"12ffffcced\", &sp, &ep); 得 sp=3、ep=6 */\n```\n要点：一趟 O(n) 游程扫描；题面样例为 1 基计数（第 3~6 个字符对应 startpos=3、endpos=6）；空串返回 -1、-1。"),
    442: ("迭代反转三指针：prev 指向已反转子链表的新头（初始 NULL），逐节点处理 head——先用 next 暂存 head 的后继（关键：改指针前必须保存，否则断链），再把 head->next 反向指向 prev，然后 prev、head 依次前移一格；循环到 head 为 NULL 时，prev 即原表尾（新表头），返回 prev。一趟 O(n)，只改指针不搬数据，空间 O(1)。对比：递归法写法短但用 O(n) 栈空间（长链表有爆栈风险，工程不推荐）；头插法重建新表要 O(n) 额外空间。边界：空表返回 NULL；单节点原样返回；返回的必须是 prev 而不是 head（结尾时 head 为 NULL）。易错点：不保存 next 导致断链；返回 head；循环条件写成 head->next（漏处理最后一个节点）。合并说明：本题与多份试卷重复题已合并，见得分点注。",
          "完整函数（含调用示例）如下：\n```c\n/* 单链表节点（题目隐含定义） */\ntypedef struct List {\n    int val;\n    struct List *next;\n} List;\n\n/* 迭代反转：返回新表头；O(n) 时间、O(1) 空间 */\nList *list_reverse(List *head)\n{\n    List *prev = NULL;\n    while (head) {\n        List *next = head->next;   /* ① 先保存后继（防断链） */\n        head->next = prev;         /* ② 当前节点反向指向前驱 */\n        prev = head;               /* ③ prev 前移 */\n        head = next;               /* ④ head 前移 */\n    }\n    return prev;                   /* 新表头＝原表尾 */\n}\n/* 调用示例：head = list_reverse(head); */\n```\n要点：三指针迭代 O(n)/O(1)；必须先存 next 再改指向；返回 prev。"),
    443: ("统计「1 的个数」（popcount）经典技巧：对每个字节反复执行 v &= (v-1)，每执行一次恰好清掉最低位的那个 1（v-1 把最低位 1 变 0、其下所有 0 变 1，与 v 相与后最低位 1 被清掉，更高位不动），循环次数等于该字节中 1 的个数——比逐位右移 &1 的固定 8 次平均更快。外层再套一层遍历 n 个字节，累加即得总数。最坏 O(n×8)（仍是 O(n)），空间 O(1)。细节：操作应在副本 v 上进行，不能改到调用者的数组；BYTE 按题目定义为 unsigned char。易错点：v-1 写成 v&-v 或顺序写错；直接改原数组；循环条件写反。延伸：还可查表法（半字节表 4 位一组）进一步加速。",
          "完整函数（含调用示例）如下：\n```c\ntypedef unsigned char BYTE;\n\n/* 统计 n 个字节中共有多少位为 1 */\nint countonenumber(BYTE b[], int n)\n{\n    int cnt = 0;\n    for (int i = 0; i < n; i++) {\n        BYTE v = b[i];\n        while (v) {                  /* Kernighan 法 */\n            cnt++;\n            v &= (v - 1);            /* 清掉最低位的 1 */\n        }\n    }\n    return cnt;\n}\n/* 调用示例：BYTE d[2] = {0x0F, 0xF0}; countonenumber(d, 2) 返回 8 */\n```\n要点：v&(v-1) 每次消掉一个 1，循环次数即 1 的个数；总体 O(n×8) 最坏、O(1) 空间。"),
    444: ("FreeRTOS 任务模型：任务是独立的无限循环函数（void f(void *参数)），由 xTaskCreate 创建（关键参数：任务函数、名字、栈深度（单位 word）、参数、优先级、句柄），最后由 vTaskStartScheduler 启动调度。任务「每 1 秒/2 秒」用 vTaskDelay 实现——它把当前任务挂起指定 tick 数并让出 CPU（不是忙等），配合 pdMS_TO_TICKS 把毫秒换算成系统节拍，与 tick 频率解耦。两个任务打印后各自延时，周期 1000ms/2000ms。要点：任务里必须含延时/阻塞点，否则同级任务得不到调度；延时用 vTaskDelay 而非空转循环。易错点：忘记 while(1)（函数返回）；忘记 vTaskDelay 或单位换算；xTaskCreate 参数顺序记错；栈空间给太小。延伸：要严格固定周期可改用 vTaskDelayUntil。",
          "完整程序如下（FreeRTOS 环境）：\n```c\n#include \"FreeRTOS.h\"\n#include \"task.h\"\n#include <stdio.h>\n\n/* 任务1：每 1 秒打印 */\nvoid Task1(void *p)\n{\n    while (1) {\n        printf(\"Task 1 is running\\n\");\n        vTaskDelay(pdMS_TO_TICKS(1000));   /* 延时 1000ms，让出 CPU */\n    }\n}\n\n/* 任务2：每 2 秒打印 */\nvoid Task2(void *p)\n{\n    while (1) {\n        printf(\"Task 2 is running\\n\");\n        vTaskDelay(pdMS_TO_TICKS(2000));\n    }\n}\n\nint main(void)\n{\n    xTaskCreate(Task1, \"T1\", 128, NULL, 1, NULL);   /* 栈 128 words、优先级 1 */\n    xTaskCreate(Task2, \"T2\", 128, NULL, 1, NULL);\n    vTaskStartScheduler();                           /* 启动调度器（不返回） */\n    return 0;\n}\n```\n要点：任务 = 含延时的死循环；vTaskDelay + pdMS_TO_TICKS 控制周期；xTaskCreate 参数顺序别记错。"),
    445: ("SPI 写时序逐拍分析：0x66=0110 0110b，MSB 先发即按 0,1,1,0,0,1,1,0 依次上 SDI。模式 0（CPOL=0/CPHA=0）下 SCK 空闲为低、上升沿采样、下降沿移出；一帧共 8 个时钟周期，期间 CS 保持低电平选中从机，SDO（MISO）同拍返回从机数据。画图顺序建议：先画 CS 阶梯（拉低→保持→拉高）、再画 8 个等宽 SCK 方波、然后把 8 个位对齐到周期内（在上升沿处保持有效）、最后标注采样沿与位序。趣味细节：0x66 的位序反转后仍是 0110 0110（回文位串），所以本题即使位序画反也不易察觉——但仍要标清 MSB 先发。易错点：SCK 个数与位数不符；采样沿方向画错；忘记 CS 起止。延伸：追问模式 1/2/3 或 LSB-first 时采样沿与位序如何变化。",
          "参考文字描述（可照着画）：\n① CS：整帧拉低选中从机（开始拉低、8 位发完拉高）；\n② SCK：画 8 个等宽时钟周期；模式 0 时空闲低电平、上升沿采样、下降沿移出；\n③ SDI（MOSI）：按 MSB-first 逐个周期输出 0、1、1、0、0、1、1、0（0x66 = 0110 0110），每位在 SCK 上升沿处保持有效；\n④ SDO（MISO）：同期返回从机数据（题图未给从机值，可标注「从机返回数据」示意）；\n⑤ 标注：位序号、采样沿、位序（MSB first）、模式 0。\n文字版：CS 拉低 → 8 个 SCK 周期，SDI 按 MSB-first 输出 0,1,1,0,0,1,1,0；SDO 同拍返回（可选）；采样边沿为上升沿（模式 0）。"),
    446: ("I2C 用 SCL、SDA 两根开漏线（需上拉，空闲均为高）。起止条件的识别规则：数据位只在 SCL 低电平期间变化，因此「SCL 高电平期间 SDA 发生跳变」就是起止信号——起始 START：SCL 高时 SDA 由高→低；停止 STOP：SCL 高时 SDA 由低→高。画图要点：两线先画空闲高电平段；在 SCL 高电平平台处画 SDA 跳变并用箭头标注；跳变必须对齐在 SCL 高电平内（画在低电平处就成普通数据位了）。易错点：跳变画在 SCL 低电平期间；两线上下顺序或方向写反；忘记空闲高电平状态。延伸：重复起始（Sr）与起始的区别、时钟延展。",
          "参考文字描述（可照着画）：\n① 空闲：SCL、SDA 均保持高电平；\n② 起始条件（START）：SCL 保持高电平时，SDA 由高→低跳变（在 SCL 高电平平台处画下降沿，旁注「起始」）；\n③ 停止条件（STOP）：SCL 保持高电平时，SDA 由低→高跳变（画上升沿，旁注「停止」）；\n④ 跳变之间是数据位规则：SDA 只在 SCL 低电平期间变化、SCL 高电平期间保持稳定；\n⑤ 绘制：SCL 在上、SDA 在下两条水平线，时间向右，跳变处加箭头注释，边沿关系正确。"),
    447: ("计算先行：周期 T=1/f=1/10Hz=100ms；PWM 平均电压=占空比×满幅电压，要求平均 2.5V、满幅 5V，则占空比=2.5/5=50%，即每周期前 50ms 输出 5V、后 50ms 输出 0V。画图要点：坐标轴横轴标时间（0、50、100、150、200ms），纵轴标电压（0、5V，可加 2.5V 平均电平虚线）；方波从 0 跳 5V、保持 50ms、再回 0、保持 50ms，重复 2~3 个周期显示周期性。易错点：周期算成 10ms（把 Hz 当周期）；占空比与电压关系算反；坐标不标数值（题目明确要求带坐标系、标坐标值）。延伸：若要求平均 1.25V 则占空比 25%，平均电压随占空比线性变化。",
          "参考文字描述（可照着画）：\n① 计算：T = 1/10Hz = 100ms；平均 2.5V / 满幅 5V ⇒ 占空比 50%；\n② 波形：0~50ms 高电平 5V、50~100ms 低电平 0V，之后重复（画 2~3 个周期）；\n③ 坐标轴：横轴 T(ms) 标 0/50/100/150/200，纵轴 V 标 0/5（可加 2.5V 平均虚线）；\n④ 数值标注：周期 100ms、占空比 50%、幅度 5V。"),
    448: ("makefile 三要素：①规则三部分「目标: 依赖」+ 命令（命令必须以 Tab 开头）；②默认目标=第一个目标，所以把 all: target 放最前，执行 make 默认编 target；③依赖链 lib.so←a.c、target←lib.so+b.c 决定构建顺序，make 只重建过期的目标。原答案中 target 链接命令的 -l 参数不完整（缺库名），本答案补为 GNU ld 的精确文件名写法 -l:lib.so（等价于直接写 ./lib.so），保证命令可用。易错点：命令行用空格缩进（make 报 missing separator）；默认目标放错（如 clean 放最前）；共享库漏 -fPIC；clean 未声明 PHONY（进阶）。",
          "完整 makefile 如下：\n```makefile\nall: target\n\nlib.so: a.c\n\tgcc -fPIC -shared -o lib.so a.c\n\ntarget: lib.so b.c\n\tgcc -o target b.c -L. -l:lib.so\n\nclean:\n\trm -f lib.so target\n```\n要点：默认目标=第一个目标 all→target；命令必须 Tab 缩进；依赖关系保证先编 lib.so 再链 target；-l 补全为精确文件名写法 -l:lib.so（或直接写 ./lib.so）。"),
    449: ("朴素（BF）子串匹配：外层枚举 hay 的每个起点，内层用两个游标 h、n 同步前进逐字符比较；若子串游标 n 先走到 '\\0'（!*n 成立）说明整段匹配、返回当前起点；外层走到结尾仍未命中返回 NULL。空 needle 约定返回 hay 本身（与标准库 strstr 语义一致）。复杂度最坏 O(n×m)：每个起点都可能比到最后一位（如主串全 a、子串以 b 结尾），n 为主串长、m 为模式长；无额外空间。优化方向：KMP 可做到 O(n+m)。易错点：匹配判定看错游标（要看 n 是否走完，而不是 h）；空串处理漏写；形参为 const char*，返回要强转 (char *)；内层失败后外层起点前移由 for 完成、内层必须用副本。延伸：返回首次出现位置指针，正是指针算术练习。",
          "完整函数（含调用示例）如下：\n```c\n/* 在 hay 中查找子串 needle 首次出现的位置；未找到返回 NULL；空 needle 返回 hay */\nchar *my_strstr(const char *hay, const char *needle)\n{\n    if (!*needle) return (char *)hay;     /* 空子串：约定返回原串 */\n    for (; *hay; hay++) {                 /* 枚举每个起点 */\n        const char *h = hay, *n = needle;\n        while (*h && *n && *h == *n) { h++; n++; }   /* 同步逐字符比较 */\n        if (!*n) return (char *)hay;      /* n 走完：匹配成功 */\n    }\n    return NULL;                          /* 未找到 */\n}\n/* 调用示例：char *p = my_strstr(\"hello world\", \"world\"); */\n```\n说明：朴素匹配最坏 O(n·m)（n、m 分别为主串与子串长度）；返回首次出现位置的指针，未找到返回 NULL。"),
    450: ("状态机设计题按「状态集合 + 迁移条件 + 状态动作」三段式答：①运行态（RUN）：执行 ADC 采样与通信轮询，空闲计时到（idle_timeout）就关外设→休眠，检出错误（error_detected）就记日志→故障；②休眠态（SLEEP）：进入低功耗、等待外部中断（EXTI）唤醒，唤醒事件（wakeup_event）到来重新初始化外设→运行；③故障态（FAULT）：进入安全状态并刷日志，故障清除（fault_cleared）后恢复外设→运行。实现用 switch 状态机最清晰，工程要点：进休眠前先关外设、配好唤醒源（否则醒不来）；故障态要让执行器处于安全状态（输出安全值）。易错点：迁移条件写漏（休眠无返回路径）；进休眠没关外设（功耗不达标）；故障态缺安全动作；不用状态机而堆 if（可维护性差）。若画流程图：三个圆圈表示状态，箭头按上述条件标注。",
          "伪代码如下（含三态的全部迁移条件）：\n```c\ntypedef enum { RUN, SLEEP, FAULT } State;\nState st = RUN;\n\nvoid fsm_loop(void)\n{\n    switch (st) {\n    case RUN:                                  /* 运行：ADC 采样 + 通信 */\n        adc_sample();\n        comm_poll();\n        if (idle_timeout)   { disable_periph(); st = SLEEP; }  /* 空闲超时→休眠 */\n        if (error_detected) { log_error();       st = FAULT; }  /* 检出错误→故障 */\n        break;\n    case SLEEP:                                /* 休眠：关外设、等外部中断 */\n        enter_low_power();                     /* 等待 EXTI 唤醒 */\n        if (wakeup_event)   { init_periph();     st = RUN; }   /* 唤醒→运行 */\n        break;\n    case FAULT:                                /* 故障：日志 + 安全状态 */\n        safe_state();\n        log_flush();\n        if (fault_cleared)  { init_periph();     st = RUN; }   /* 故障清除→运行 */\n        break;\n    }\n}\n```\n要点：三态 + 条件（idle_timeout→SLEEP、error_detected→FAULT、wakeup_event/fault_cleared→RUN）；休眠关外设、故障进安全状态。流程图同构：三个状态圆圈，箭头按上述条件标注。"),
    451: ("环形缓冲区的空满判定用「牺牲一个单元」法：head 指向下一个写入位、tail 指向下一个读出位，head==tail 表示空，而 (head+1)%QUEUE_SIZE==tail 表示满——因为满时 head 也会「追上」tail，通过永远保留一个空位把「满」与「空」区分开，实际容量为 QUEUE_SIZE-1=15 个事件。入队三步：算 next、判满（满返回 0）、写入并前移 head；出队：判空（空返回 0）、取值并前移 tail；下标一律取模回绕。所有操作 O(1)、无动态分配。工程细节：中断与主循环共享时 head、tail 加 volatile；真正多任务访问需临界区或保证单生产者单消费者。易错点：判空/判满条件写反；回绕漏 %QUEUE_SIZE；忽略牺牲单元导致容量多算；忘记 volatile 或共享保护。题目要求 initBuffer/enqueue/dequeue，事件类型 FireEvent{ID/Value/timestamp}。",
          "完整实现如下：\n```c\n#define QUEUE_SIZE 16          /* 缓冲区单元数；实际可存 QUEUE_SIZE-1 个事件 */\n\ntypedef struct {\n    int ID;                    /* 报警 ID */\n    int Value;                 /* 报警值 */\n    unsigned int timestamp;    /* 时间戳 */\n} FireEvent;\n\ntypedef struct ringbuffer_s {\n    FireEvent buf[QUEUE_SIZE];\n    volatile int head;         /* 写入位置 */\n    volatile int tail;         /* 读出位置 */\n} RingBuffer;\n\nvoid initBuffer(RingBuffer *q) { q->head = q->tail = 0; }\n\nint enqueue(RingBuffer *q, FireEvent event)\n{\n    int next = (q->head + 1) % QUEUE_SIZE;\n    if (next == q->tail) return 0;          /* 满：入队失败 */\n    q->buf[q->head] = event;\n    q->head = next;\n    return 1;\n}\n\nint dequeue(RingBuffer *q, FireEvent *event)\n{\n    if (q->head == q->tail) return 0;       /* 空：出队失败 */\n    *event = q->buf[q->tail];\n    q->tail = (q->tail + 1) % QUEUE_SIZE;\n    return 1;\n}\n/* 用法：initBuffer(&q)；enqueue(&q, ev)；dequeue(&q, &ev) */\n```\n要点：牺牲一个单元区分空满（空 = head==tail、满 = (head+1)%SIZE==tail）；下标取模回绕；1 成功 / 0 失败；多任务共享加临界区。"),
    452: ("排序键思路：IPv4 点分十进制四段各占 8 位，打包成 32 位整数（a<<24 | b<<16 | c<<8 | d）即可把 IP 映射为无符号整数——整数序与 IP 字典序一致，问题转化为整数排序，直接 qsort O(n log n)。必须用无符号数：255 左移 24 位若放 int 中会溢出（有符号溢出是未定义行为），所以键与移位都按 unsigned 处理。也可用伪代码描述「按四段逐段比较」的思路。易错点：直接按字符串排序（\"10.x\" 会排在 \"9.x\" 前，错误）；有符号左移溢出；sscanf 未检查返回值（非法 IP 需兜底）；比较器要返回三值（<0/0/>0）。延伸：IPv6 或带端口时应按字节数组逐段比较。",
          "完整程序如下（C，转 32 位整数键 + qsort）：\n```c\n#include <stdio.h>\n#include <stdlib.h>\n\n/* \"a.b.c.d\" 转 32 位无符号整数键：整数序与 IP 序一致 */\nunsigned int ip_key(const char *ip)\n{\n    unsigned int a, b, c, d;\n    sscanf(ip, \"%u.%u.%u.%u\", &a, &b, &c, &d);\n    return (a << 24) | (b << 16) | (c << 8) | d;   /* 用 unsigned 防溢出 */\n}\n\n/* qsort 比较器：按整数键升序 */\nint cmp_ip(const void *p, const void *q)\n{\n    unsigned int x = ip_key(*(const char * const *)p);\n    unsigned int y = ip_key(*(const char * const *)q);\n    return (x > y) - (x < y);\n}\n\nint main(void)\n{\n    const char *ips[] = {\"192.168.1.10\", \"10.0.0.2\", \"172.16.5.4\",\n                         \"8.8.8.8\", \"192.168.1.2\"};\n    int n = sizeof(ips) / sizeof(ips[0]);\n    qsort(ips, n, sizeof(ips[0]), cmp_ip);\n    for (int i = 0; i < n; i++) printf(\"%s\\n\", ips[i]);\n    return 0;\n}\n```\n要点：IP → 32 位键 → qsort O(n log n)；键必须 unsigned；比较器用 (x>y)-(x<y) 保证三值语义。"),
    453: ("指针实现拼接两步走：①「找尾」——p 从 dst 头出发 while(*p) p++ 停在 dst 的 '\\0' 处，即追加起始点；②「追加」——while ((*p++ = *src++)) 把 src 的每个字符（包括结尾 '\\0'）拷到 p 处并整体后移，赋值表达式的值就是刚拷入的字符，遇到 '\\0'（值 0）循环结束，保证目标串以 '\\0' 正确收尾。返回 dst（与标准库 strcat 一致）便于链式调用。复杂度 O(len(dst)+len(src))；空间 O(1) 原地。安全前提：调用方保证 dst 缓冲区剩余空间足够（工程实现会先判断长度或用 snprintf）。易错点：缓冲区不足溢出；指针未先移到 dst 结尾（从头覆盖）；漏拷 '\\0'；返回值类型写错。测试例程覆盖「已含内容 + 追加」与空串两种情形。",
          "完整函数与测试例程如下：\n```c\n#include <stdio.h>\n\n/* 把 src 拼到 dst 末尾，返回 dst；要求 dst 空间足够 */\nchar *str_cat(char *dst, const char *src)\n{\n    char *p = dst;\n    while (*p) p++;                 /* ① 找到 dst 结尾 */\n    while ((*p++ = *src++))         /* ② 逐字符追加（含 '\\0'） */\n        ;\n    return dst;\n}\n\nint main(void)\n{\n    char buf[64] = \"Hello, \";\n    str_cat(buf, \"World!\");\n    puts(buf);                      /* Hello, World! */\n\n    char buf2[64] = \"\";\n    str_cat(buf2, \"abc\");\n    puts(buf2);                     /* abc */\n    return 0;\n}\n```\n要点：先寻尾再逐字符拷贝（含 '\\0'）；返回 dst；O(len) 时间、O(1) 额外空间；需保证目标缓冲足够。"),
    454: ("判断括号匹配用「深度计数 + 提前失败」：遇左括号深度加一，遇右括号先减一——若减到负说明右括号多余，立即返回不匹配（不必等扫描结束，可提前发现 \")(\" 一类错序）；直到串尾深度恰为 0 才匹配。细节：题目样例含全角括号，必须与半角 () 一起识别；注意「多字节字符常量」的坑——直接写 *s == '（' 这类比较时，编译器把全角字符当作多字节整型常量（GCC 会告警 multi-character character constant），其值不等于字符串中的单个字节，判定必然失败；稳妥做法是对字符串字面量 \"（\" 逐字节比较（仍不调用任何库函数），匹配后整体跳过该字符的多个字节。正确性：计数法等价于「任意前缀深度非负 + 末尾深度 0」，O(n)/O(1)。易错点：只识别半角括号；用多字节字符常量比较（见上）；不提前失败；结尾忘判深度=0；跳过全角字符时步进字节数写错。",
          "完整函数与测试例程如下：\n```c\n#include <stdio.h>\n\n/* 判断 s 处是否以 str 开头；返回匹配的字节数（0 = 不匹配）。不用库函数 */\nstatic int match_at(const char *s, const char *str)\n{\n    int i = 0;\n    while (str[i] && s[i] == str[i]) i++;\n    return str[i] ? 0 : i;      /* 全部比完返回字节数，否则 0 */\n}\n\n/* 括号匹配检查：支持半角 () 与全角（）；匹配返回 1，不匹配返回 0 */\nint brackets_match(const char *s)\n{\n    int depth = 0, n;\n    while (*s) {\n        if (*s == '(') { depth++; s++; }                        /* 半角左 */\n        else if (*s == ')') { if (--depth < 0) return 0; s++; } /* 半角右 */\n        else if ((n = match_at(s, \"（\")) > 0) { depth++; s += n; }   /* 全角左 */\n        else if ((n = match_at(s, \"）\")) > 0) {\n            if (--depth < 0) return 0;   /* 右括号多余：提前失败 */\n            s += n;\n        } else {\n            s++;                         /* 其他字符跳过 */\n        }\n    }\n    return depth == 0;                   /* 深度归零才匹配 */\n}\n\nint main(void)\n{\n    printf(\"%d\\n\", brackets_match(\"（11）2（33）（4）\"));  /* 1：匹配 */\n    printf(\"%d\\n\", brackets_match(\"（113）3（\"));          /* 0：不匹配 */\n    return 0;\n}\n```\n要点：深度计数 + 右括号多余立即失败；结尾深度为 0 才匹配；全角括号按字符串字面量逐字节比较（避开多字节字符常量的坑），O(n)/O(1)。"),
    455: ("从后往前合并的理由：A 的尾部有 m 个空位，先把「最大的数」放到 A 的最末尾（k=n+m-1），两个指针 i、j 分别指向 A[n-1]、B[m-1] 当前最大值取较大者填入——空位在尾部，写进去不会覆盖尚未处理的元素；反过来从前往后写，就会把 A 里尚未读出的较小元素覆盖掉。循环到 j<0（B 全部并入）结束：此时 A 剩余元素本来就在结果前缀里、无需搬动；i<0 而 j>=0 时条件 i>=0 为假、自动取 B[j]。时间 O(n+m)（每个元素比较一次）、空间 O(1)。易错点：方向选错（从前往后覆盖）；条件漏 i>=0 保护（i 变负后 A[i] 越界）；循环终止条件写成 i>=0（漏放 B 的剩余元素）。",
          "完整函数（含调用示例）如下：\n```c\n/* 把升序数组 B（m 个）并入升序数组 A（前 n 个有效、空间足够）；从后往前合并 */\nvoid merge(int *A, int n, int *B, int m)\n{\n    int i = n - 1, j = m - 1, k = n + m - 1;\n    while (j >= 0)                                   /* B 全部放完即结束 */\n        A[k--] = (i >= 0 && A[i] > B[j]) ? A[i--] : B[j--];\n}\n/* 调用示例：int A[10] = {1,3,5,7}; int B[2] = {2,4}; merge(A,4,B,2); 结果 1,2,3,4,5,7 */\n```\n要点：尾部双指针从后往前 O(n+m)/O(1)；i>=0 保护；相等时取 B（有序性不受影响）。"),
    456: ("中序遍历 =「左→根→右」：先递归遍历左子树，再访问根节点（本题为打印），最后递归右子树；空节点是递归出口。命名的由来：按「根」的访问位置记忆——根在中间是中序、根在最前是前序、根在最后是后序。重要性质：二叉搜索树的中序遍历得到升序序列（常用于校验 BST、找第 k 小等）。复杂度：每节点恰好访问一次 O(n) 时间；递归栈深等于树高 h（平衡树 O(log n)、退化成链最坏 O(n)）。易错点：顺序写错（先访问根再递归左）；漏空指针出口；打印格式与题目要求不符。延伸：非递归版用显式栈；Morris 遍历可做到 O(1) 额外空间。",
          "完整函数（含调用示例）如下：\n```c\n/* 二叉树节点定义 */\ntypedef struct Node {\n    int data;\n    struct Node *left;\n    struct Node *right;\n} Node;\n\n/* 中序遍历：左 → 根 → 右（递归） */\nvoid inorder(Node *root)\n{\n    if (!root) return;            /* 递归出口：空树 */\n    inorder(root->left);          /* ① 左子树 */\n    printf(\"%d \", root->data);    /* ② 根 */\n    inorder(root->right);         /* ③ 右子树 */\n}\n/* 调用示例：inorder(tree); 若 tree 为二叉搜索树，输出为升序 */\n```\n要点：中序 = 左→根→右；O(n) 时间、O(h) 栈空间；BST 中序即升序。"),
    457: ("逐字符比较：只要「尚未到 source 结尾」且「两字符相等」就双指针后移；循环退出的原因只有两种——字符不等、或 source 到了 '\\0'。退出后用一行判断统一收口：*source==*dest 说明两者恰好同时到达串尾（即完全相等）返回 0，否则返回 -1。注意题目语义：只要 0 和 -1 两个值，不是标准库「返回差值」的语义，别画蛇添足。复杂度 O(min(n,m))~O(n)，空间 O(1)。易错点：按标准库差值语义返回（题目只要 0/-1）；把相等判断写错；循环与判断里指针推进不一致。",
          "完整函数（含调用示例）如下：\n```c\n/* 比较两字符串：相等返回 0，不等返回 -1（不使用库函数）；\n   注意题目为二值语义，与标准库返回差值的语义不同 */\nint my_strcmp(char *source, char *dest)\n{\n    while (*source && *source == *dest) {   /* 逐字符比较 */\n        source++;\n        dest++;\n    }\n    return (*source == *dest) ? 0 : -1;     /* 同时到 '\\0' 即相等 */\n}\n/* 调用示例：my_strcmp(\"abc\", \"abc\") 返回 0；my_strcmp(\"abc\", \"abd\") 返回 -1 */\n```\n要点：0/-1 二值语义；循环退出后统一判断；O(min(n,m)) 时间、O(1) 空间。"),
    458: ("WGS84 大地坐标转地心直角坐标（ECEF）公式推导要点：地球取旋转椭球（长半轴 a=6378137m、第一偏心率平方 e2=0.00669437999014），先算卯酉圈曲率半径 N=a/√(1-e2·sin²B)——它代表该纬度处椭球面法线方向的曲率半径；X、Y 等于 (N+H)·cosB 投影到经度方向（分别乘 cosL、sinL）；Z 用 [N·(1-e2)+H]·sinB，其中 (1-e2) 因子体现椭球在两极方向被压扁（极向半径小于赤道半径）。输入 B、L 必须用弧度（度转弧度=度×π/180），公式才有意义。时间 O(1)。易错点：度/弧度混用（最常见）；Z 项漏乘 (1-e2)；e2 与 e（偏心率）混淆；B、L 顺序搞反（B 是纬度）；忘记叠加 H。自检：H=0 时 X²/a²+Y²/a²+Z²/(a²(1-e2))=1 在椭球面上成立。",
          "完整函数（含调用示例）如下：\n```c\n#include <math.h>\n\n/* WGS84 椭球常数 */\n#define WGS84_A   6378137.0            /* 长半轴（米） */\n#define WGS84_E2  0.00669437999014     /* 第一偏心率平方 */\n\n/* 大地坐标 (B 纬度 rad, L 经度 rad, H 高程 m) → 地心直角坐标 (X, Y, Z)，单位米 */\nvoid blh_to_xyz(double B, double L, double H, double *X, double *Y, double *Z)\n{\n    double N = WGS84_A / sqrt(1 - WGS84_E2 * sin(B) * sin(B));  /* 卯酉圈曲率半径 */\n    *X = (N + H) * cos(B) * cos(L);\n    *Y = (N + H) * cos(B) * sin(L);\n    *Z = (N * (1 - WGS84_E2) + H) * sin(B);\n}\n/* 调用示例：double x,y,z;\n   blh_to_xyz(30*3.14159265358979323846/180, 114*3.14159265358979323846/180, 0, &x,&y,&z); */\n```\n要点：N=a/√(1-e²sin²B)；Z 项含 (1-e²) 椭球修正；输入必须为弧度；O(1)。"),
    460: ("atoi 的逐位累加原理：num = num*10 + (c-'0')——每读一位把已有结果扩大十倍再补新位；符号位在转换前单独处理（'-' 则 sign=-1、'+' 跳过）；遇到第一个非数字字符或 '\\0' 结束。本题合并的另一版本要求跳过前导空格（空格/制表符），故完整实现先吃掉空白再收符号。'0' 的 ASCII 是 48，用 c-'0' 把字符转为数值，比查表简洁。复杂度 O(位数)。易错点：忘记负号；sign 应用位置搞错（最后乘即可）；空格未处理（合并题要求）；遇非数字未及时停（继续累加出错）；超 int 范围溢出未处理（进阶考点，标准 atoi 对此行为未定义）。",
          "完整函数（含调用示例）如下：\n```c\n/* 字符串转整数（仿 atoi）：跳过前导空白，可带 +/-，遇非数字结束 */\nint Atoi(char str[])\n{\n    int i = 0, sign = 1, num = 0;\n    while (str[i] == ' ' || str[i] == '\\t') i++;    /* 跳过前导空白 */\n    if (str[i] == '-') { sign = -1; i++; }          /* 处理符号 */\n    else if (str[i] == '+') i++;\n    while (str[i] >= '0' && str[i] <= '9')          /* 逐位累加 */\n        num = num * 10 + (str[i++] - '0');\n    return sign * num;\n}\n/* 调用示例：Atoi(\"-123\") 返回 -123；Atoi(\" 45x\") 返回 45 */\n```\n要点：符号 + 逐位 num*10+digit；遇非数字或 '\\0' 结束；合并题要求跳过前导空格（已包含）。"),
    462: ("固定长度循环队列的「牺牲一个单元」设计：head 指向出队位置、tail 指向入队位置；空判断 head==tail；满判断 (tail+1)%QSIZE==head——缓冲区永远留一个空位来区分空与满，因此 10 个格子的队列最多存 9 个元素。入队：判满→存 tail 处→tail 回绕前移；出队：判空→取 head 处→head 回绕前移。全部操作 O(1)、无动态内存。易错点：容量理解错（说成能存 10 个）；% QSIZE 漏写导致下标越界；两判断写反；入队先移指针后存数据（覆盖）。扩展：多生产者/消费者场景需临界区或原子操作；也可用 count 计数器法（不浪费单元但多一个变量）。题目要求结构体、InitQueue、IsQueueEmpty、IsQueueFull、EnQueue、DeQueue 全套接口。",
          "完整实现如下：\n```c\n#include <stdint.h>\n\n#define QSIZE 10               /* 缓冲区格子数；实际最多存 QSIZE-1 个元素 */\n\ntypedef struct {\n    uint8_t data[QSIZE];\n    int head;                  /* 出队位置 */\n    int tail;                  /* 入队位置 */\n} Queue;\n\nvoid InitQueue(Queue *q) { q->head = q->tail = 0; }\n\nint IsQueueEmpty(Queue *q) { return q->head == q->tail; }        /* 空：重合 */\nint IsQueueFull(Queue *q)  { return (q->tail + 1) % QSIZE == q->head; }  /* 满：下一格是 head */\n\nint EnQueue(Queue *q, uint8_t v)\n{\n    if (IsQueueFull(q)) return 0;          /* 满：失败 */\n    q->data[q->tail] = v;\n    q->tail = (q->tail + 1) % QSIZE;       /* 回绕前移 */\n    return 1;\n}\n\nint DeQueue(Queue *q, uint8_t *v)\n{\n    if (IsQueueEmpty(q)) return 0;         /* 空：失败 */\n    *v = q->data[q->head];\n    q->head = (q->head + 1) % QSIZE;\n    return 1;\n}\n/* 用法：InitQueue(&q); EnQueue(&q, 5); DeQueue(&q, &v) */\n```\n要点：牺牲一个单元判满（(tail+1)%SIZE==head）；空为 head==tail；1 成功 / 0 失败；实际容量 9。"),
    463: ("用理想运放「虚短 + 虚断」两条金律列节点方程：①虚短使反相端电位=同相端=0V（虚地），虚断使输入电流不流入运放——输入电流 I=Ui/R1 全部经 R2 流向 T 型中点 M；②由 R2 上电流-电压关系得 V_M=-I·R2=-(Ui/R1)·R2；③对 M 点分流：经 R3 入地的电流 I3=-V_M/R3=I·(R2/R3)，因此流出 M 经 R4 去输出的总电流为 I+I3=I·(1+R2/R3)；④由 R4 支路方程 V_M-Uo=(I+I3)·R4 解出 Uo，代入整理得 Au=Uo/Ui=-(R2+R4+R2·R4/R3)/R1。T 型网络的意义：R2·R4/R3 乘积项能放大等效反馈电阻——用 3 个不大不小的电阻实现大增益（单电阻反馈要达到同样倍数需要极大阻值）。按题目提示可设电阻相等/成倍数化简：例如 R2=R3=R4=R 时 Au=-3R/R1。易错点：M 点电流方向/符号弄反；漏掉 R3 支路电流；虚短虚断用错地方；最后负号丢失。",
          "推导与结果如下（可照此写答题卡）：\n① 设输入 Ui、输出 Uo，反相端虚地（0V），输入电流 I = Ui/R1；\n② I 全部经 R2 到 T 型中点 M ⇒ V_M = -I·R2 = -(R2/R1)·Ui；\n③ M 点分流：经 R3 入地 I3 = -V_M/R3 = (R2/R3)·I，经 R4 到输出 I4 = I + I3 = I·(1 + R2/R3)；\n④ R4 上电压关系：V_M - Uo = I4·R4 ⇒ Uo = V_M - I·(1 + R2/R3)·R4；\n⑤ 代入整理得放大倍数：Au = Uo/Ui = -(R2 + R4 + R2·R4/R3) / R1；\n按提示设定比例化简示例：R2=R3=R4=R ⇒ Au = -3R/R1（反相）。\n要点：虚短虚断 + 节点 KCL；结果 -(R2+R4+R2·R4/R3)/R1；等值化简只改变表达式形式、不影响结论。"),
    464: ("三运放仪放 = 前级两个同相放大器 + 后级差分放大器。前级的作用是把输入差放大且输入阻抗极高：两运放经 Rgain 耦合，虚短使 Rgain 两端恰好承受输入差 vd=V1-V2，流过 Rgain 的电流 vd/Rgain 又串联流过两个反馈电阻 R（同一支路电流相同），因此前级输出差放大到 vd+2·R·(vd/Rgain)=vd·(1+2R/Rgain)——注意系数 2 的来源是路径上有两个 R。后级差分放大器对前级输出差再做 R2/R1 倍放大（R1 为输入网络、R2 为反馈网络）。总增益相乘 G=(1+2R/Rgain)·(R2/R1)。设计特点：输入阻抗高（信号直进同相端）、增益由单个电阻 Rgain 线性调节。画图要点：三个运放三角形、两个 R 与 Rgain 的跨接关系、后级四个电阻 R1/R2 网络、输入 V1/V2 与输出标注。易错点：前级增益漏掉「2R/Rgain」的 2；后级增益比写成 R1/R2（反了）；Rgain 不画在两反相端之间而画成接地；输出取自前级（应取后级）。",
          "画图与推导（可照着画、照步骤写）：\n① 电路：A1、A2 两个同相放大器——V1、V2 分别接同相端，A1 输出经 R 接回 A1 反相端、A2 输出经 R 接回 A2 反相端，两反相端之间跨接 Rgain；后级 A3 差分放大器——A1、A2 输出经两个 R1 接 A3 反相/同相端，配两个 R2 网络，A3 输出为总输出 Uo；\n② 前级推导：虚短使 Rgain 两端电压 = 输入差 vd = V1 - V2 ⇒ 电流 vd/Rgain 同流过两个 R ⇒ 前级输出差 = vd + 2·R·(vd/Rgain) = vd·(1 + 2R/Rgain)；\n③ 后级：差分放大器差模增益 = R2/R1；\n④ 总增益：G = Uo/vd = (1 + 2R/Rgain) × (R2/R1)；\n标注要素：三运放符号、两个 R、Rgain、R1/R2 网络、V1/V2 与 Uo。\n要点：前级「1+2R/Rgain」、后级「R2/R1」相乘；高输入阻抗、单电阻调增益。"),
    466: ("O(N) 去重随机的标准解法是「部分洗牌」（Fisher–Yates 变体）：先把候选池（1~100）按序摆好，对前 N 个位置 i 依次做——从 [i, 99] 中随机挑一个位置 j 与位置 i 交换，然后把位置 i 的数收进结果。因为每当一个数被取走，就把「后面的某个数」换到前面来补充候选，池的前缀始终是「已取走集合」、后缀是「未取的随机排列」，所以每个位置只处理一次、每次 O(1)，总 O(N) 且严格不重复。要点与边界：随机范围必须是 [i, 99]（含到已用区会重复）；RandNum(x) 接口返回 [1, x] 时下标换算 RandNum(100-i)-1+i；N≤100；静态池与初始化标志注意多次调用。对比：拒绝采样或 O(N²) 查重不满足最坏 O(N)。易错点：随机区间写成 [0, 99]；忘记减 1 换算 0 基；N>100 未防护。延伸：蓄水池抽样用于「数据流中随机取 N 个」。",
          "完整函数（含调用示例）如下：\n```cpp\n#include <vector>\n\n/* 设 RandNum(x) 返回 [1, x] 的均匀随机整数（题目给定接口） */\n\n/* 从 [1,100] 中随机取 n 个不重复整数；O(n) 部分洗牌法 */\nvoid GetRandomNumbers(int n, std::vector<int> &result)\n{\n    static int pool[100];\n    static bool init = false;\n    if (!init) {                           /* 首次调用：初始化 1~100 池 */\n        for (int i = 0; i < 100; i++) pool[i] = i + 1;\n        init = true;\n    }\n    if (n > 100) n = 100;                  /* 边界保护 */\n    for (int i = 0; i < n; i++) {          /* 前 n 个位置做部分洗牌 */\n        int j = RandNum(100 - i) - 1 + i;  /* 随机位置 j ∈ [i, 99] */\n        std::swap(pool[i], pool[j]);\n        result.push_back(pool[i]);         /* 取出即不重复 */\n    }\n}\n/* 调用示例：std::vector<int> v; GetRandomNumbers(10, v); */\n```\n要点：Fisher–Yates 部分洗牌 O(n)；j 的区间必须是 [i, 99]；已取数换出前缀、保证不重复。"),
    467: ("封装顺序 = 数据域→校验→加密：①「数据域」4 字节浮点电量用 memcpy 取浮点的内存字节表示（注意跨平台字节序约定，收发两端一致即可）；②先对明文算 CRC16（校验覆盖 4 字节数据域），再与数据拼成 6 字节帧；③整帧交给 AES-128 加密输出——机密性由 AES 提供、完整性由 CRC 提供。为什么先校验后加密：接收端解密后先验 CRC 可第一时间剔除坏包；CRC 作为校验域放到帧尾。工程细节：浮点直接按结构体发送存在对齐/填充风险，memcpy 到定长缓冲是正确姿势；AES 按 16 字节分组工作，实际组帧时通常填充到分组长度再加密（题目按封装接口调用即可）；密钥不该硬编码在源码里。复杂度：CRC O(长度)、AES O(分组数)，均为常数级。易错点：memcpy 长度与偏移写错；输出缓冲不足；接口参数顺序记错；忽略字节序。",
          "完整函数如下（crc16 / aes128_encrypt 为平台或工程已有实现）：\n```c\n#include <stdint.h>\n#include <string.h>\n\n/* 假定平台提供：CRC16 计算、AES-128 加密接口 */\nextern uint16_t crc16(const uint8_t *data, uint32_t len);\nextern void aes128_encrypt(const uint8_t *in, uint32_t len, uint8_t *out, const uint8_t key[16]);\n\nstatic const uint8_t key[16] = {0};   /* 实际密钥由工程配置（此处占位） */\n\n/* 封装数据包：4 字节浮点电量 + CRC16，整帧 AES-128 加密后输出 */\nvoid build_telemetry_packet(float energy, uint8_t *output)\n{\n    uint8_t plain[4];\n    uint8_t buf[6];\n    uint16_t crc;\n\n    memcpy(plain, &energy, 4);                /* ① 数据域：4 字节浮点电量 */\n    crc = crc16(plain, 4);                    /* ② 对数据域算 CRC16 */\n    memcpy(buf, plain, 4);                    /* 组帧：4 字节数据 + 2 字节校验 */\n    memcpy(buf + 4, &crc, 2);\n    aes128_encrypt(buf, 6, output, key);      /* ③ 整帧 AES-128 加密输出 */\n}\n```\n要点：数据域 → CRC16 → AES-128 的顺序；offset 0..3 数据、4..5 校验；字节序与密钥按工程约定；AES 实际按 16 字节分组（需填充时在封装层处理）。"),
    468: ("一趟遍历同时求最大最小：把 max、min 都初始化为 a[0]（关键！不能初始化为 0——数组若全为负数，max 初值 0 会得出错误结果），然后从 a[1] 起逐个与 max、min 比较并更新；共走 n-1 步、每步至多两次比较。时间 O(n)、空间 O(1)。进阶优化：两两分组（先互相比较、再分别与 max/min 比）可把比较次数降到约 3n/2；分治法同样 O(n)。易错点：初值取 0；从下标 0 开始比较（初值未定就比）；忽略全负数场景。扩展：数组可能为空需先判长度；求第二大等其他统计量可在此基础上扩展。",
          "完整程序如下：\n```c\n#include <stdio.h>\n\nint main(void)\n{\n    int a[10], i;\n    int max, min;\n\n    printf(\"请输入 10 个整数: \");\n    for (i = 0; i < 10; i++) scanf(\"%d\", &a[i]);\n\n    max = min = a[0];              /* 以首元素为初值（防全负数组出错） */\n    for (i = 1; i < 10; i++) {     /* 一趟遍历 */\n        if (a[i] > max) max = a[i];\n        if (a[i] < min) min = a[i];\n    }\n    printf(\"max=%d min=%d\\n\", max, min);\n    return 0;\n}\n```\n要点：初值必须取 a[0]；一趟 O(n)；结果与元素顺序无关。"),
    470: ("链表实现栈的核心是头插法：栈顶就放在链表头——push 分配节点、把 next 指向原栈顶、再更新栈顶指针（O(1)）；pop 取栈顶值后先记住 next、再 free 旧顶、更新栈顶（O(1)）；top 直接访问栈顶值；empty 判断栈顶指针是否为 NULL。链表栈相比数组栈：容量动态无上限、不需预估大小；代价是每元素一次动态分配/释放、节点多一个指针开销。工程要点：malloc 判空；pop/top 前判空（空栈访问会崩）；free 前先保存 next（防悬挂）。易错点：忘记判空；pop 不保存 next 直接 free；忘记维护 size；malloc 失败未处理。扩展：实时性敏感场景可预分配节点池避免运行时分配。",
          "完整实现（含调用示例）如下：\n```c\n#include <stdlib.h>\n\ntypedef struct Node {\n    int v;\n    struct Node *next;\n} Node;\n\ntypedef struct {\n    Node *top_;        /* 栈顶：链表头 */\n    int size;          /* 元素个数 */\n} Stack;\n\nvoid init(Stack *s)  { s->top_ = NULL; s->size = 0; }\nint  empty(Stack *s) { return s->top_ == NULL; }\n\nvoid push(Stack *s, int v)\n{\n    Node *n = malloc(sizeof(Node));\n    if (!n) return;                    /* 分配失败：不动栈 */\n    n->v = v;\n    n->next = s->top_;                 /* 头插 */\n    s->top_ = n;\n    s->size++;\n}\n\nint pop(Stack *s)\n{\n    if (empty(s)) return -1;           /* 空栈保护 */\n    Node *n = s->top_;\n    int v = n->v;\n    s->top_ = n->next;                 /* 先记 next 再 free */\n    free(n);\n    s->size--;\n    return v;\n}\n\nint top(Stack *s) { return empty(s) ? -1 : s->top_->v; }\n/* 用法：init(&s); push(&s, 1); top(&s); pop(&s); empty(&s) */\n```\n要点：头插法 + 各操作 O(1)；pop 先记 next 再 free；pop/top 判空保护；链表栈动态容量、无溢出。"),
    471: ("删除所有值为 val 的节点，难点是「连续删除头节点」的处理——引入哨兵（dummy）节点挂在表头前，令所有删除都变成「删除某个节点的后继」，逻辑统一、无需特判头指针。算法：p 从 dummy 出发，看 p->next：值为 val 就摘链删除（保存待删节点、p->next 跳过它、delete 释放，注意此时 p 不前移）；否则 p 前移一格；直到 p->next 为空。返回 dummy.next 作为新头（原头可能已被删）。因为每个节点最多检查一次，O(n)/O(1)。C 语言等价写法可用 malloc 哨兵或二级指针。易错点：删除时错误地前移 p（漏删连续节点）；忘记释放（若题目要求 delete）；返回 head 而非 dummy.next；边界（空表、全删）漏测。",
          "完整函数（含调用示例）如下：\n```cpp\n/* 单链表节点定义 */\nstruct ListNode {\n    int val;\n    ListNode *next;\n};\n\n/* 删除所有值为 val 的节点，返回新头（哨兵节点法） */\nListNode* removeElements(ListNode* head, int val)\n{\n    ListNode dummy{0, head};        /* 哨兵：dummy.next = head */\n    ListNode *p = &dummy;\n    while (p->next) {\n        if (p->next->val == val) {\n            ListNode *del = p->next;    /* 摘链并释放 */\n            p->next = del->next;\n            delete del;                 /* 删除时 p 不前移 */\n        } else {\n            p = p->next;                /* 非目标：前移 */\n        }\n    }\n    return dummy.next;              /* 新头 */\n}\n/* 调用示例：head = removeElements(head, 6); */\n```\n要点：哨兵统一「删头/删中间」；删除时不前移 p、可连续删；O(n)/O(1)。"),
    472: ("原地逆序字符串用「双指针交换」：左指针从头、右指针从尾（strlen(s)-1），向中间靠拢，逐对交换字符；循环条件 s<e 保证奇数长度时中间字符无需处理、偶数长度时恰好换完；空串时 e=s-1 循环直接不进，安全。只用了两个指针加一个交换临时字符，满足「不额外分配空间」（O(1) 空间）、时间 O(n)。易错点：测试用字符串字面量（只读，写入崩溃）——必须用字符数组；循环条件写成 s<=e（多一次自交换，无害但可指正）；strlen 依赖串以 '\\0' 结尾（非法串越界）；忘记包含 string.h。延伸：递归版（首尾交换后递归内层）是 O(n) 栈空间，不如迭代。",
          "完整函数与测试例程如下：\n```c\n#include <stdio.h>\n#include <string.h>\n\n/* 原地逆序字符串：双指针两端向中间交换，O(1) 额外空间 */\nvoid str_reverse(char *s)\n{\n    char *e = s + strlen(s) - 1;      /* 指向最后一个字符 */\n    while (s < e) {                   /* 两端向中间靠拢 */\n        char t = *s;\n        *s++ = *e;\n        *e-- = t;\n    }\n}\n\nint main(void)\n{\n    char t[] = \"hello\";\n    str_reverse(t);\n    puts(t);                          /* olleh */\n    return 0;\n}\n```\n要点：双指针原地交换 O(n)/O(1)；测试必须用可修改的字符数组；空串/单字符天然安全。"),
}

if __name__ == "__main__":
    assert len(NEW) == 33, len(NEW)
    n_code = 0
    for n, (a, s) in NEW.items():
        assert "\n" not in a, ("解析含换行", n)
        assert "**" not in a and "**" not in s, ("含 **", n)
        for ln in a.split("\n"):
            assert not ln.startswith(("#", "---")), (n, ln[:20])
        in_fence = False
        for ln in s.split("\n"):
            if ln.strip().startswith("```"):
                in_fence = not in_fence
                continue
            if not in_fence:
                assert not ln.startswith(("#", "---", "**")), (n, ln[:20])
            else:
                n_code += 1
    print("OK", len(NEW), "题；解析最长", max(len(a) for a, _ in NEW.values()),
          "；代码行数", n_code)
